# Check if there's any hint in the environment or files about how to finish
import os

# Check for any config files
for root, dirs, files in os.walk('.'):
    if '.git' in root or '__pycache__' in root or 'node_modules' in root:
        continue
    for f in files:
        if f.endswith(('.json', '.yaml', '.yml', '.toml', '.cfg', '.ini')):
            path = os.path.join(root, f)
            print(f"Config-like file: {path}")

# Check env vars for hints
for key in sorted(os.environ.keys()):
    val = os.environ[key]
    if len(val) > 0 and len(val) < 200:
        print(f"ENV: {key}={val}")
